'use strict';
// Presentation of the original project → tender file / bidders → bid files contract.
const bamBase={handleAction,modalContent,pickerModal};
function bamProjectSummary(p){return '招标 '+p.tender.length+' 份 · '+p.bidders.length+' 家单位 · 投标 '+p.bidders.reduce((n,b)=>n+b.files.length,0)+' 份';}
function bamScrollRender(selector){const top=$('.ba-material-scroll')?.scrollTop||0;render();const list=$('.ba-material-scroll');if(list)list.scrollTop=top;if(selector)requestAnimationFrame(()=>{const el=$(selector);el?.scrollIntoView({block:'nearest'});el?.focus({preventScroll:true});});}
function bamOpenEntity(kind,project,index){const p=ws().projects.find(p=>p.id===project),editing=kind.startsWith('edit'),unit=kind.endsWith('unit');if(editing&&(!p||unit&&!p.bidders[index]))return;openModal('bam-entity',{kind,project,index,name:editing?(unit?p.bidders[index].name:p.name):'',error:''});requestAnimationFrame(()=>{$('#bam-entity-name')?.focus();if(editing)$('#bam-entity-name')?.select();});}
function bamUnits(p){const q=baView.unitQuery.trim().toLowerCase(),units=p.bidders.map((b,index)=>({b,index})).filter(({b})=>(b.name+' '+b.files.map(id=>file(id)?.name).join(' ')).toLowerCase().includes(q)),pages=Math.max(1,Math.ceil(units.length/10));baView.unitPage=Math.max(1,Math.min(baView.unitPage,pages));baView.bamOpenUnits??={};return '<section class="bam-units"><div class="bam-section-head"><h3>投标单位 <strong>'+p.bidders.length+'</strong></h3>'+B(I('plus','icon-sm')+'添加单位','add-bidder','soft sm','data-id="'+E(p.id)+'" aria-label="为'+E(p.name)+'添加投标单位"')+'</div>'+(p.bidders.length>5?'<div class="search ba-unit-search">'+I('search','icon-sm')+'<input id="ba-unit-query" data-ba-input="units" aria-label="查找投标单位或文件" placeholder="查找单位或文件" value="'+E(baView.unitQuery)+'"></div>':'')+units.slice((baView.unitPage-1)*10,baView.unitPage*10).map(({b,index})=>{const key=p.id+':'+index,open=baView.bamOpenUnits[key]??(index===0||!b.name||!b.files.length);return '<details class="bam-unit" data-bam-unit="'+E(key)+'" '+(open?'open':'')+'><summary><span class="bam-unit-index">'+(index+1)+'</span><span class="bam-unit-title"><b title="'+E(b.name||'未填写单位名称')+'">'+E(b.name||'未填写单位名称')+'</b><small>'+(b.files.length?'<strong>'+b.files.length+'</strong> 份投标文件':'待添加投标文件')+'</small></span>'+I('chevron','icon-sm')+'</summary><div class="bam-unit-body"><div class="bam-unit-actions">'+A('修改名称','bam-edit-unit','data-project="'+E(p.id)+'" data-index="'+index+'"')+A('移除单位','remove-bidder','data-project="'+E(p.id)+'" data-index="'+index+'" title="移出本次分析，原文件保留"')+'</div>'+baFiles(b.files,p,'bid',index)+B(I('plus','icon-sm')+(b.files.length?'管理投标文件':'选择投标文件'),'pick-bid','sm bam-file-picker '+(b.files.length?'':'soft'),'data-project="'+E(p.id)+'" data-role="bid" data-index="'+index+'" aria-label="'+E(b.name||'此单位')+'：'+(b.files.length?'管理':'选择')+'投标文件"')+'</div></details>';}).join('')+(!units.length?'<p class="bam-empty-note">'+(q?'没有匹配的单位或文件。':'先添加投标单位，再选择该单位的投标文件。')+'</p>':'')+(pages>1?'<div class="ba-small-pages">'+B('上一页','ba-unit-page','sm','data-step="-1" '+(baView.unitPage===1?'disabled':''))+'<span>单位 '+((baView.unitPage-1)*10+1)+'–'+Math.min(baView.unitPage*10,units.length)+' / '+units.length+'</span>'+B('下一页','ba-unit-page','sm','data-step="1" '+(baView.unitPage===pages?'disabled':''))+'</div>':'')+'</section>';}
function bamProjectCard(p,index){const active=baView.project===p.id&&!baView.bamProjectClosed,issue=baProjectIssue(p);return '<section class="bam-project '+(active?'is-active':'')+'" data-bam-project="'+E(p.id)+'"><div class="bam-project-head"><button class="bam-project-toggle" data-action="bam-project" data-id="'+E(p.id)+'" aria-expanded="'+active+'"><span class="bam-project-index">'+(index+1)+'</span><span class="bam-project-title"><b title="'+E(p.name||'未命名项目')+'">'+E(p.name||'未命名项目')+'</b><small>'+bamProjectSummary(p)+'</small></span>'+I(active?'down':'chevron','icon-sm')+'</button></div>'+(active?'<div class="bam-project-body"><div class="bam-project-tools"><span id="ba-project-status" class="'+(issue?'ba-waiting':'ba-ready')+'">'+E(issue||'资料已配齐')+'</span><div>'+baIcon('bam-edit-project','edit','修改项目名称','data-id="'+E(p.id)+'"')+(ws().projects.length>1?baIcon('remove-project','trash','移除项目及文件关联，原文件保留','data-id="'+E(p.id)+'"'):'')+'</div></div><section class="bam-tender"><div class="bam-section-head"><h3>招标文件 <strong>'+p.tender.length+'</strong></h3>'+(p.tender.length?B('更换文件','pick-bid','ghost sm','data-project="'+E(p.id)+'" data-role="tender"'):'')+'</div>'+baFiles(p.tender,p,'tender')+(!p.tender.length?B(I('plus','icon-sm')+'选择招标文件','pick-bid','sm soft bam-file-picker','data-project="'+E(p.id)+'" data-role="tender"')+'<p class="bam-empty-note">每个项目选择 1 份招标文件。</p>':'')+'</section>'+bamUnits(p)+'</div>':'<div class="bam-project-collapsed"><span class="'+(issue?'ba-waiting':'ba-ready')+'">'+E(issue||'资料已配齐')+'</span></div>')+'</section>';}
baMaterials=function(){const w=ws();baProject();const s=baStats(),ready=w.projects.filter(p=>!baProjectIssue(p)).length;return '<aside class="ba-materials ew-materials bam-materials" aria-label="Step 1 添加项目资料"><div class="ba-panel-head"><h2><span class="tw-step">Step 1</span> 添加项目资料</h2>'+B('添加项目','add-project','soft sm')+'</div><p class="bam-guide">按项目添加招标文件，再按投标单位添加投标文件。</p><div class="bam-project-count"><span>项目 <strong>'+w.projects.length+'</strong></span><small>资料配齐 <strong>'+ready+'</strong> / '+w.projects.length+'</small></div><div class="ba-material-scroll">'+baPending()+w.projects.map(bamProjectCard).join('')+(!w.projects.length?'<div class="bam-empty-project"><h3>先添加一个分析项目</h3><p>同一项目的招标文件和投标文件放在一起。</p>'+B(I('plus','icon-sm')+'添加项目','add-project','soft')+'</div>':'')+'</div><div class="ba-material-footer"><span>本次 <strong>'+s.projects+'</strong> 个项目 · 招标 <strong>'+s.tender+'</strong> 份 · 投标 <strong>'+s.bid+'</strong> 份</span></div></aside>';};
modalContent=function(){if(baPreparing()&&modal==='bam-entity'){const d=modalData,unit=d.kind.endsWith('unit'),editing=d.kind.startsWith('edit'),p=ws().projects.find(p=>p.id===d.project),label=unit?'投标单位名称':'项目名称';return modalFrame((editing?'修改':'添加')+(unit?'投标单位':'项目'),unit?'所属项目：'+(p?.name||'未命名项目'):'同一项目内分别添加招标文件和各单位的投标文件。','<label class="field"><span>'+label+' <b class="red">*</b></span><input id="bam-entity-name" maxlength="100" autocomplete="off" aria-label="'+label+'" aria-required="true" aria-invalid="'+!!d.error+'" placeholder="'+(unit?'如：华信建设有限公司':'如：办公楼维修改造项目')+'" value="'+E(d.name)+'"></label><p id="bam-entity-error" class="error" role="alert">'+E(d.error||'')+'</p>',B('取消','close-modal')+B(editing?'保存名称':unit?'添加单位':'添加项目','bam-save-entity','primary'),'small bam-entity-dialog');}return bamBase.modalContent();};
pickerModal=function(){const html=bamBase.pickerModal();if(!baPreparing()||modal!=='picker'||!modalData.bid)return html;const d=modalData,p=ws().projects.find(p=>p.id===d.project),unit=p?.bidders[d.index],root=document.createElement('div');root.innerHTML=html;root.querySelector('.modal')?.classList.add('bam-file-dialog');const title=root.querySelector('.modalhead h2,.modalhead h3'),hint=root.querySelector('.modalhead p');if(title)title.innerHTML=(d.role==='tender'?'选择招标文件':'选择投标文件')+(title.querySelector('.picker-ready-inline')?.outerHTML||'');if(hint)hint.textContent='所属项目：'+(p?.name||'未命名项目')+(d.role==='bid'?' / 投标单位：'+(unit?.name||'未命名单位'):'');const confirm=root.querySelector('[data-action="confirm-picker"]');if(confirm)confirm.textContent=d.role==='tender'?'确认招标文件':'确认投标文件（'+d.selected.length+'）';return root.innerHTML;};
handleAction=function(action,el){if(!baPreparing())return bamBase.handleAction(action,el);const ds=el?.dataset||{},w=ws();
 if(action==='add-project')return bamOpenEntity('add-project');
 if(action==='add-bidder')return bamOpenEntity('add-unit',ds.id);
 if(action==='bam-edit-project')return bamOpenEntity('edit-project',ds.id);
 if(action==='bam-edit-unit')return bamOpenEntity('edit-unit',ds.project,Number(ds.index));
 if(action==='bam-project'){if(baView.project===ds.id)baView.bamProjectClosed=!baView.bamProjectClosed;else{baView.project=ds.id;baView.bamProjectClosed=false;baView.unitQuery='';baView.unitPage=1;}bamScrollRender();return;}
 if(action==='bam-save-entity'&&modal==='bam-entity'){const d=modalData,name=$('#bam-entity-name').value.trim(),p=w.projects.find(p=>p.id===d.project),unit=d.kind.endsWith('unit');d.name=name;if(!name){d.error='请填写'+(unit?'投标单位名称':'项目名称');const error=$('#bam-entity-error');if(error)error.textContent=d.error;$('#bam-entity-name').setAttribute('aria-invalid','true');$('#bam-entity-name').focus();return;}if((unit||d.kind==='edit-project')&&!p)return;
  let focus='';if(d.kind==='add-project'){const id='p'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);w.projects.push({id,name,tender:[],bidders:[]});baView.project=id;baView.bamProjectClosed=false;baView.unitQuery='';baView.unitPage=1;focus='[data-bam-project="'+id+'"] [data-action="pick-bid"]';}
  if(d.kind==='edit-project')p.name=name;
  if(d.kind==='add-unit'){p.bidders.push({name,files:[]});baView.unitQuery='';baView.unitPage=Math.ceil(p.bidders.length/10);baView.bamOpenUnits??={};baView.bamOpenUnits[p.id+':'+(p.bidders.length-1)]=true;focus='[data-bam-unit="'+p.id+':'+(p.bidders.length-1)+'"] [data-action="pick-bid"]';}
  if(d.kind==='edit-unit'&&p.bidders[d.index])p.bidders[d.index].name=name;
  closeModal();persist();bamScrollRender(focus);return;
 }
 if(action==='remove-bidder')baView.bamOpenUnits={};
 return bamBase.handleAction(action,el);
};
window.addEventListener('click',e=>{const summary=e.target.closest?.('[data-bam-unit]>summary');if(baPreparing()&&summary){const unit=summary.parentElement;baView.bamOpenUnits??={};baView.bamOpenUnits[unit.dataset.bamUnit]=!unit.open;}},true);
window.addEventListener('input',e=>{if(baPreparing()&&modal==='bam-entity'&&e.target.id==='bam-entity-name'){modalData.name=e.target.value;if(modalData.error&&e.target.value.trim()){modalData.error='';e.target.setAttribute('aria-invalid','false');const error=$('#bam-entity-error');if(error)error.textContent='';}}},true);
window.addEventListener('keydown',e=>{if(baPreparing()&&modal==='bam-entity'&&e.target.id==='bam-entity-name'&&e.key==='Enter'&&!e.isComposing){e.preventDefault();handleAction('bam-save-entity',e.target);}},true);
render();
